    void httpSemantics_suppressionEndpoints() throws Exception {
        mockMvc.perform(post("/api/exposure/campaigns")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestId\":\"h-c1\",\"campaignId\":\"ch\",\"dailyTotalCap\":10,"
